package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.exception.FileStorageException; // 👈 အသစ် Import လုပ်ထားပါသည်import org.springframework.stereotype.Service;import org.springframework.util.StringUtils;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.nio.file.StandardCopyOption;import java.util.ArrayList;import java.util.List;import java.util.UUID;@Servicepublic class FileStorageServiceImpl implements FileStorageService {    // ဖိုင်များ သိမ်းဆည်းမည့် ပင်မ Folder အမည် (Project Directory အတွင်း တည်ဆောက်မည်)    private final String uploadDir = "uploads/tickets/";    private final Path fileStorageLocation;    public FileStorageServiceImpl() {        this.fileStorageLocation = Paths.get(uploadDir).toAbsolutePath().normalize();        try {            // Folder မရှိသေးပါက အလိုအလျောက် တည်ဆောက်မည်            Files.createDirectories(this.fileStorageLocation);        } catch (Exception ex) {            // 🎯 RuntimeException အစား FileStorageException ပြောင်းသုံးထားပါသည်            throw new FileStorageException("Could not create the directory where the uploaded files will be stored.", ex);        }    }    @Override    public List<String> storeFiles(List<MultipartFile> files) {        List<String> fileNames = new ArrayList<>();        for (MultipartFile file : files) {            if (!file.isEmpty()) {                String fileName = storeFile(file);                fileNames.add(fileName);            }        }        return fileNames;    }    @Override    public String storeFile(MultipartFile file) {        // မူရင်း ဖိုင်အမည်ကို ယူခြင်း        String originalFileName = StringUtils.cleanPath(file.getOriginalFilename());        try {            // လုံခြုံရေးအရ ဖိုင်အမည်တွင် မပါဝင်သင့်သော စာသားများ ပါ/မပါ စစ်ဆေးခြင်း            if (originalFileName.contains("..")) {                // 🎯 RuntimeException အစား FileStorageException ပြောင်းသုံးထားပါသည်                throw new FileStorageException("Sorry! Filename contains invalid path sequence " + originalFileName);            }            // ဖိုင်အမည်များ မထပ်စေရန် UUID ကို ရှေ့ကပ်ပေးခြင်း (ဥပမာ: 123e4567-e89b..._screenshot.png)            String fileExtension = "";            int dotIndex = originalFileName.lastIndexOf(".");            if (dotIndex > 0) {                fileExtension = originalFileName.substring(dotIndex);            }            String newFileName = UUID.randomUUID().toString() + fileExtension;            // ဖိုင်ကို ကူးယူသိမ်းဆည်းမည့် လမ်းကြောင်း အပြည့်အစုံ သတ်မှတ်ခြင်း            Path targetLocation = this.fileStorageLocation.resolve(newFileName);            // ဖိုင်ကို ရွေးချယ်ထားသော နေရာသို့ ကူးယူသိမ်းဆည်းခြင်း (ရှိပြီးသားဆိုလျှင် အစားထိုးမည်)            Files.copy(file.getInputStream(), targetLocation, StandardCopyOption.REPLACE_EXISTING);            // သိမ်းဆည်းလိုက်သော ဖိုင်၏ လမ်းကြောင်း (သို့မဟုတ် URL အဖြစ်သုံးမည့် အမည်) ကို ပြန်ပေးခြင်း            return uploadDir + newFileName;        } catch (IOException ex) {            // 🎯 RuntimeException အစား FileStorageException ပြောင်းသုံးထားပါသည်            throw new FileStorageException("Could not store file " + originalFileName + ". Please try again!", ex);        }    }}